164→            await deleteMutation.mutateAsync({type, ids: selectedRows});
165→            setSelectedRows([]);
166→            setDeleteDialogOpen(false);
167→            toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
168→        } catch (error) {
169→            toast.error('삭제 중 오류가 발생했습니다.');
170→        }
171→    };
172→
173→    // Determine if this is a SYNONYM type to show direction
174→    const isSynonymType = category === 'SYNONYM';
175→    const isSetType = category === 'SET';
176→    const isSpaceType = type === 'SPACE';
177→    const isCompoundType = type === 'COMPOUND';
178→
179→    // Get direction from dictionary item (bidirectional if keyword is null or empty string)
180→    const getDirection = (item: Dictionary) => {
181→        return item.keyword === null || item.keyword === '' ? 'bidirectional' : 'unidirectional';
182→    };
183→
184→    // Render value as badges
