193→                ))}
194→            </div>
195→        );
196→    };
197→
198→    return (
199→        <div className="space-y-4">
200→            {/* Toolbar */}
201→            <div className="flex flex-wrap items-center justify-between gap-4 bg-card p-4 border rounded-lg">
202→                <div className="flex items-center gap-2">
203→                    <Select value={searchField} onValueChange={(v) => setSearchField(v as 'all' | 'keyword' | 'value')}>
204→                        <SelectTrigger className="w-[120px]">
205→                            <SelectValue placeholder="필터"/>
206→                        </SelectTrigger>
207→                        <SelectContent>
208→                            <SelectItem value="all">전체</SelectItem>
209→                            {!isSetType && <SelectItem value="keyword">Keyword</SelectItem>}
210→                            <SelectItem value="value">{isSetType ? '단어' : 'Value'}</SelectItem>
211→                        </SelectContent>
