  3→import {useState} from "react";
  4→import {Table, TableBody, TableCell, TableHead, TableHeader, TableRow,} from "@/components/ui/table";
  5→import {Button} from "@/components/ui/button";
  6→import {Checkbox} from "@/components/ui/checkbox";
  7→import {Badge} from "@/components/ui/badge";
  8→import {AlertCircle, CheckCircle2, Loader2, Play, RefreshCw,} from "lucide-react";
  9→import {useCompileDictionary, useDictionaryOverview} from "@/hooks/use-dictionary";
 10→import type {DictionaryType} from "@/types";
 11→import {DICTIONARY_NAMES} from "@/types";
 12→import {toast} from "sonner";
 13→
 14→// 사전 타입 순서 정의
 15→const DICTIONARY_TYPE_ORDER: DictionaryType[] = [
 16→    'STOP',
 17→    'USER',
 18→    'ENGLISH',
 19→    'UNIT',
 20→    'SYNONYM',
 21→    'UNIT_SYNONYM',
 22→    'SPACE',
 23→    'COMPOUND',
 24→];
 25→
 26→export function DictionaryOverview() {
 27→    const [selectedTypes, setSelectedTypes] = useState<DictionaryType[]>([]);
 28→
 29→    const {data, isLoading, isError, refetch} = useDictionaryOverview();
 30→    const compileMutation = useCompileDictionary();
 31→
 32→    const items = data?.items || [];
 33→
 34→    // 타입 순서대로 정렬된 아이템
 35→    const sortedItems = DICTIONARY_TYPE_ORDER.map((type) =>
 36→        items.find((item) => item.type === type)
 37→    ).filter(Boolean);
 38→
 39→    const allTypesSelected = selectedTypes.length === DICTIONARY_TYPE_ORDER.length;
 40→    const someTypesSelected = selectedTypes.length > 0 && !allTypesSelected;
 41→
 42→    const toggleSelectAll = (checked: boolean) => {
 43→        if (checked) {
 44→            setSelectedTypes([...DICTIONARY_TYPE_ORDER]);
 45→        } else {
 46→            setSelectedTypes([]);
 47→        }
 48→    };
 49→
 50→    const toggleSelectType = (type: DictionaryType, checked: boolean) => {
 51→        if (checked) {
 52→            setSelectedTypes((prev) => [...prev, type]);
 53→        } else {
 54→            setSelectedTypes((prev) => prev.filter((t) => t !== type));
 55→        }
 56→    };
 57→
 58→    const handleCompile = async () => {
 59→        if (selectedTypes.length === 0) return;
 60→
 61→        try {
 62→            const results = await compileMutation.mutateAsync({types: selectedTypes});
 63→            const totalCount = results.reduce((sum, r) => sum + r.count, 0);
 64→            toast.success(
 65→                <div className="flex items-center gap-2">
 66→                    <CheckCircle2 className="h-4 w-4 text-green-500"/>
 67→                    <span>
 68→            {selectedTypes.length}개 사전이 적용되었습니다. (총 {totalCount.toLocaleString()}개 단어)
 69→          </span>
 70→                </div>
 71→            );
 72→            setSelectedTypes([]);
 73→        } catch {
 74→            toast.error('사전 적용 중 오류가 발생했습니다.');
 75→        }
 76→    };
 77→
 78→    const formatDateTime = (dateString: string | null) => {
 79→        if (!dateString) return '-';
 80→        const date = new Date(dateString);
 81→        return date.toLocaleString('ko-KR', {
 82→            year: 'numeric',
 83→            month: '2-digit',
 84→            day: '2-digit',
 85→            hour: '2-digit',
 86→            minute: '2-digit',
 87→        });
 88→    };
 89→
 90→    return (
 91→        <div className="space-y-4">
 92→            {/* Toolbar */}
 93→            <div className="flex items-center justify-between bg-card p-4 border rounded-lg">
 94→                <div className="flex items-center gap-3">
 95→                    <Button
 96→                        onClick={handleCompile}
 97→                        disabled={selectedTypes.length === 0 || compileMutation.isPending}
 98→                    >
 99→                        {compileMutation.isPending ? (
100→                            <Loader2 className="mr-2 h-4 w-4 animate-spin"/>
101→                        ) : (
102→                            <Play className="mr-2 h-4 w-4"/>
103→                        )}
104→                        사전적용
105→                        {selectedTypes.length > 0 && (
106→                            <Badge variant="secondary" className="ml-2">
107→                                {selectedTypes.length}
108→                            </Badge>
109→                        )}
110→                    </Button>
111→                </div>
112→
113→                <Button
114→                    variant="outline"
115→                    size="sm"
116→                    onClick={() => refetch()}
117→                    disabled={isLoading}
118→                >
119→                    <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`}/>
120→                </Button>
121→            </div>
122→
123→            {/* Table */}
124→            <div className="rounded-md border bg-background">
125→                {isLoading ? (
126→                    <div className="flex items-center justify-center h-64">
127→                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground"/>
128→                    </div>
129→                ) : isError ? (
130→                    <div className="flex flex-col items-center justify-center h-64 text-muted-foreground">
131→                        <AlertCircle className="h-8 w-8 mb-2"/>
132→                        <p>데이터를 불러오는데 실패했습니다.</p>
133→                        <Button variant="link" onClick={() => refetch()}>다시 시도</Button>
134→                    </div>
135→                ) : (
136→                    <Table>
137→                        <TableHeader>
138→                            <TableRow>
139→                                <TableHead className="w-[50px]">
140→                                    <Checkbox
141→                                        checked={allTypesSelected}
142→                                        ref={(el) => {
143→                                            if (el) {
144→                                                (el as unknown as HTMLInputElement).indeterminate = someTypesSelected;
145→                                            }
146→                                        }}
147→                                        onCheckedChange={(checked) => toggleSelectAll(!!checked)}
148→                                    />
149→                                </TableHead>
150→                                <TableHead>이름</TableHead>
151→                                <TableHead className="w-[120px]">타입</TableHead>
152→                                <TableHead className="w-[120px] text-right">단어 수</TableHead>
153→                                <TableHead className="w-[180px]">수정시간</TableHead>
154→                            </TableRow>
155→                        </TableHeader>
156→                        <TableBody>
157→                            {sortedItems.length === 0 ? (
158→                                <TableRow>
159→                                    <TableCell colSpan={5} className="text-center text-muted-foreground h-32">
160→                                        등록된 사전이 없습니다.
161→                                    </TableCell>
162→                                </TableRow>
163→                            ) : sortedItems.map((item) => item && (
164→                                <TableRow key={item.type}>
165→                                    <TableCell>
166→                                        <Checkbox
167→                                            checked={selectedTypes.includes(item.type)}
168→                                            onCheckedChange={(checked) => toggleSelectType(item.type, !!checked)}
169→                                        />
170→                                    </TableCell>
171→                                    <TableCell className="font-medium">
172→                                        {DICTIONARY_NAMES[item.type]}
173→                                    </TableCell>
174→                                    <TableCell>
175→                                        <Badge variant="outline" className="font-mono text-xs">
176→                                            {item.type}
177→                                        </Badge>
178→                                    </TableCell>
179→                                    <TableCell className="text-right tabular-nums">
180→                                        {item.count.toLocaleString()}
181→                                    </TableCell>
182→                                    <TableCell className="text-muted-foreground text-sm">
183→                                        {formatDateTime(item.lastModified)}
184→                                    </TableCell>
185→                                </TableRow>
186→                            ))}
187→                        </TableBody>
188→                    </Table>
189→                )}
190→            </div>
191→
192→            {/* Summary */}
193→            <div className="text-sm text-muted-foreground">
194→                총 {sortedItems.length}개 사전
195→                {sortedItems.length > 0 && (
196→                    <span className="ml-2">
197→            · 전체 단어 수: {sortedItems.reduce((sum, item) => sum + (item?.count || 0), 0).toLocaleString()}개
198→          </span>
199→                )}
200→            </div>
201→        </div>
202→    );
203→}
