'use client';

import {useMutation, useQuery, useQueryClient} from '@tanstack/react-query';
import apiClient from '@/lib/api/client';
import {mapCursorDictionaryResponse} from '@/lib/api/dictionary-mapper';
import type {
    BackendCursorResponse,
    BackendDictionary,
    CompileResult,
    CursorPaginatedResponse,
    Dictionary,
    DictionaryOverviewResponse,
    DictionaryType,
} from '@/types';

// ========================================
// Query Keys
// ========================================

export const analysisKeys = {
    all: ['analysis'] as const,
    dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
    dictionaryList: (type: DictionaryType, cursor?: string | null, search?: string, sortType?: SortType) =>
        [...analysisKeys.dictionaries(), type, {cursor, search, sortType}] as const,
    dictionaryOverview: () => [...analysisKeys.all, 'overview'] as const,
};

// ========================================
// Dictionary List Hooks (Cursor-based)
// ========================================

export type SortType = 'UPDATED' | 'KEYWORD';

interface DictionaryListParams {
    type: DictionaryType;
    cursor?: string | null;
    pageSize?: number;
    search?: string;
    searchField?: 'all' | 'keyword' | 'value';
    wordMatch?: boolean;
    sortType?: SortType;
}

export function useDictionaries(params: DictionaryListParams) {
    const {type, cursor = null, pageSize = 20, search, wordMatch = false, sortType = 'UPDATED'} = params;

    return useQuery({
        queryKey: analysisKeys.dictionaryList(type, cursor, search, sortType),
        queryFn: async (): Promise<CursorPaginatedResponse<Dictionary>> => {
            // If search is provided, use search endpoint (returns array)
            if (search && search.trim()) {
                const response = await apiClient.get<BackendDictionary[]>(
                    `/api/v1/dictionary/${type}/search`,
                    {
                        params: {
                            word: search,
                            isMatch: wordMatch,
                        },
                    }
                );
                // Convert search results to cursor response format (flat structure)
                const items = response.data;
                return {
                    items: items.map((item) => ({
                        id: item.id,
                        type: item.type,
                        keyword: item.keyword,
                        value: item.value ?? '',
                        createdAt: item.createdTime,
                        updatedAt: item.updatedTime,
                    })),
                    total: items.length,
                    nextCursor: null,
                    hasNext: false,
                };
            }

            // Cursor-based list endpoint - avoids ES from+size 10,000 limit
            const response = await apiClient.get<BackendCursorResponse>(
                `/api/v1/dictionary/${type}`,
                {
                    params: {
                        size: pageSize,
                        sort: sortType,
                        ...(cursor && {cursor}),
                    },
                }
            );
            return mapCursorDictionaryResponse(response.data);
        },
        staleTime: 30000, // 30 seconds
    });
}

// ========================================
// Dictionary CRUD Hooks
// ========================================

interface CreateDictionaryParams {
    type: DictionaryType;
    keyword?: string | null;
    value?: string | null;
}

export function useCreateDictionary() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: async (params: CreateDictionaryParams) => {
            const response = await apiClient.post(
                '/api/v1/dictionary',
                {
                    keyword: params.keyword,
                    type: params.type,
                    value: params.value,
                }
            );
            return response.data;
        },
        onSuccess: (_, variables) => {
            queryClient.invalidateQueries({
                queryKey: analysisKeys.dictionaryList(variables.type),
            });
        },
    });
}

interface UpdateDictionaryParams {
    type: DictionaryType;
    id: string;
    keyword?: string | null;
    value?: string | null;
}

export function useUpdateDictionary() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: async (params: UpdateDictionaryParams) => {
            const response = await apiClient.put(
                `/api/v1/dictionary/${params.id}`,
                {
                    keyword: params.keyword ?? '',
                    type: params.type,
                    value: params.value,
                }
            );
            return response.data;
        },
        onSuccess: (_, variables) => {
            queryClient.invalidateQueries({
                queryKey: analysisKeys.dictionaryList(variables.type),
            });
        },
    });
}

interface DeleteDictionaryParams {
    type: DictionaryType;
    ids: string[];
}

export function useDeleteDictionary() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: async (params: DeleteDictionaryParams) => {
            // Backend only supports single delete, so we delete in parallel
            await Promise.all(
                params.ids.map(id =>
                    apiClient.delete(`/api/v1/dictionary/${id}`)
                )
            );
        },
        onSuccess: (_, variables) => {
            queryClient.invalidateQueries({
                queryKey: analysisKeys.dictionaryList(variables.type),
            });
        },
    });
}

// ========================================
// Dictionary Overview Hook
// ========================================

export function useDictionaryOverview() {
    return useQuery({
        queryKey: analysisKeys.dictionaryOverview(),
        queryFn: async (): Promise<DictionaryOverviewResponse> => {
            const response = await apiClient.get<DictionaryOverviewResponse>(
                '/api/v1/dictionary/last-modified'
            );
            return response.data;
        },
        staleTime: 30000, // 30 seconds
    });
}

// ========================================
// Dictionary Compile Hook
// ========================================

interface CompileDictionaryParams {
    types: DictionaryType[];
}

export function useCompileDictionary() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: async (params: CompileDictionaryParams): Promise<CompileResult[]> => {
            const {types} = params;

            // If all 8 types are selected, use the bulk compile endpoint
            if (types.length === 8) {
                const response = await apiClient.post<CompileResult[]>(
                    '/api/v1/dictionary/compile'
                );
                return response.data;
            }

            // Otherwise, compile each type individually in parallel
            const results = await Promise.all(
                types.map(async (type) => {
                    const response = await apiClient.post<CompileResult>(
                        `/api/v1/dictionary/compile/${type}`
                    );
                    return response.data;
                })
            );
            return results;
        },
        onSuccess: () => {
            // Invalidate overview to refresh lastModified times
            queryClient.invalidateQueries({
                queryKey: analysisKeys.dictionaryOverview(),
            });
        },
    });
}
