import {Separator} from "@/components/ui/separator";
import {Alert, AlertDescription} from "@/components/ui/alert";
import {AlertCircle, ArrowLeftRight, ArrowRight, Info, Loader2,} from "lucide-react";
import {useCreateDictionary, useUpdateDictionary} from "@/hooks/use-dictionary";
import type {Dictionary, DictionaryCategory, DictionaryType} from "@/types";
import {DICTIONARY_CATEGORY_MAP, DICTIONARY_TYPE_LABELS} from "@/types";
import {toast} from "sonner";

// ========================================
// Helper Functions
// ========================================

function getCategory(type: DictionaryType): DictionaryCategory {
    return DICTIONARY_CATEGORY_MAP[type];
}

function getTypeLabel(type: DictionaryType): string {
    return DICTIONARY_TYPE_LABELS[type];
}

function parseCommaSeparated(value: string): string[] {
    return value.split(',').map(v => v.trim()).filter(Boolean);
}

// ========================================
// Preview Components
// ========================================

interface SynonymPreviewProps {
    direction: 'bidirectional' | 'unidirectional';
    keyword: string;
    value: string;
}

function SynonymPreview({direction, keyword, value}: SynonymPreviewProps) {
    const synonyms = parseCommaSeparated(value);

    if (synonyms.length === 0) return null;

    return (
        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
            <p className="font-medium text-muted-foreground">적용 미리보기</p>
            {direction === 'bidirectional' ? (
                <div className="space-y-1">
                    {synonyms.slice(0, 2).map((word, i) => (
                        <p key={i} className="text-xs">
                            &quot;{word}&quot; 검색 → {synonyms.map((s, j) => (
                            <Badge key={j} variant="secondary" className="mx-0.5 text-xs">{s}</Badge>
                        ))} 결과
                        </p>
                    ))}
                </div>
            ) : (
                <div className="space-y-1">
                    <p className="text-xs">
                        {synonyms.map((s, i) => (
                            <span key={i}>&quot;{s}&quot;{i < synonyms.length - 1 ? ', ' : ''}</span>
                        ))} 검색 → &quot;{keyword}&quot;로 인식
                    </p>
                    <p className="text-xs text-muted-foreground">
                        &quot;{keyword}&quot; 검색 → &quot;{keyword}&quot;만 결과 (역방향 X)
                    </p>
                </div>
            )}
        </div>
    );
}

interface MapPreviewProps {
    type: DictionaryType;
    keyword: string;
    value: string;
}

function MapPreview({type, keyword, value}: MapPreviewProps) {
    const parts = parseCommaSeparated(value);

    if (!keyword || parts.length === 0) return null;

    return (
        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
            <p className="font-medium text-muted-foreground">
                {type === 'SPACE' ? '변환' : type === 'COMPOUND' ? '색인' : '변환'} 미리보기
            </p>
            <div className="space-y-1">
                <p className="text-xs">
                    &quot;{keyword}&quot; → {parts.map((p, i) => (
                    <Badge key={i} variant="secondary" className="mx-0.5 text-xs">{p}</Badge>
                ))}
                </p>
                {type === 'COMPOUND' && (
                    <p className="text-xs text-muted-foreground">
                        &quot;{parts[0]}&quot; 검색 → &quot;{keyword}&quot; 문서도 검색 가능
                    </p>
                )}
            </div>
        </div>
    );
}

// ========================================
// Add Dictionary Dialog
// ========================================

interface AddDictionaryDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    type: DictionaryType;
}

export function AddDictionaryDialog({open, onOpenChange, type}: AddDictionaryDialogProps) {
    const category = getCategory(type);
    const createMutation = useCreateDictionary();

    // Form state
    const [keyword, setKeyword] = useState("");
    const [value, setValue] = useState("");
    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');

    // Validation
    const [errors, setErrors] = useState<string[]>([]);

    // Reset form when dialog opens
    useEffect(() => {
        if (open) {
            setKeyword("");
            setValue("");
            setSynonymDirection('bidirectional');
            setErrors([]);
        }
    }, [open]);

    const validate = (): boolean => {
        const newErrors: string[] = [];

        if (category === 'SET') {
            if (!value.trim()) {
                newErrors.push("단어를 입력해주세요.");
            }
        } else if (category === 'SYNONYM') {
            if (type === 'SYNONYM') {
                if (synonymDirection === 'bidirectional') {
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.length < 2) {
                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
                    }
                } else {
                    if (!keyword.trim()) {
                        newErrors.push("대표 단어를 입력해주세요.");
                    }
                    if (!value.trim()) {
                        newErrors.push("동의어 목록을 입력해주세요.");
                    }
                    // Check for self-loop
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.includes(keyword.trim())) {
                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
                    }
                }
            } else {
                // UNIT_SYNONYM
                if (!keyword.trim()) {
                    newErrors.push("대상 표현을 입력해주세요.");
                }
                if (!value.trim()) {
                    newErrors.push("정규화 기호를 입력해주세요.");
