"use client";

import {useState} from "react";
import {Table, TableBody, TableCell, TableHead, TableHeader, TableRow,} from "@/components/ui/table";
import {Button} from "@/components/ui/button";
import {Checkbox} from "@/components/ui/checkbox";
import {Badge} from "@/components/ui/badge";
import {AlertCircle, CheckCircle2, Loader2, Play, RefreshCw,} from "lucide-react";
import {useCompileDictionary, useDictionaryOverview} from "@/hooks/use-dictionary";
import type {DictionaryType} from "@/types";
import {DICTIONARY_NAMES} from "@/types";
import {toast} from "sonner";

// 사전 타입 순서 정의
const DICTIONARY_TYPE_ORDER: DictionaryType[] = [
    'STOP',
    'USER',
    'ENGLISH',
    'UNIT',
    'SYNONYM',
    'UNIT_SYNONYM',
    'SPACE',
    'COMPOUND',
];

export function DictionaryOverview() {
    const [selectedTypes, setSelectedTypes] = useState<DictionaryType[]>([]);

    const {data, isLoading, isError, refetch} = useDictionaryOverview();
    const compileMutation = useCompileDictionary();

    const items = data?.items || [];

    // 타입 순서대로 정렬된 아이템
    const sortedItems = DICTIONARY_TYPE_ORDER.map((type) =>
        items.find((item) => item.type === type)
    ).filter(Boolean);

    const allTypesSelected = selectedTypes.length === DICTIONARY_TYPE_ORDER.length;
    const someTypesSelected = selectedTypes.length > 0 && !allTypesSelected;

    const toggleSelectAll = (checked: boolean) => {
        if (checked) {
            setSelectedTypes([...DICTIONARY_TYPE_ORDER]);
        } else {
            setSelectedTypes([]);
        }
    };

    const toggleSelectType = (type: DictionaryType, checked: boolean) => {
        if (checked) {
            setSelectedTypes((prev) => [...prev, type]);
        } else {
            setSelectedTypes((prev) => prev.filter((t) => t !== type));
        }
    };

    const handleCompile = async () => {
        if (selectedTypes.length === 0) return;

        try {
            const results = await compileMutation.mutateAsync({types: selectedTypes});
            const totalCount = results.reduce((sum, r) => sum + r.count, 0);
            toast.success(
                <div className="flex items-center gap-2">
                    <CheckCircle2 className="h-4 w-4 text-green-500"/>
                    <span>
            {selectedTypes.length}개 사전이 적용되었습니다. (총 {totalCount.toLocaleString()}개 단어)
          </span>
                </div>
            );
            setSelectedTypes([]);
        } catch {
            toast.error('사전 적용 중 오류가 발생했습니다.');
        }
    };

    const formatDateTime = (dateString: string | null) => {
        if (!dateString) return '-';
        const date = new Date(dateString);
        return date.toLocaleString('ko-KR', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
        });
    };

    return (
        <div className="space-y-4">
            {/* Toolbar */}
            <div className="flex items-center justify-between bg-card p-4 border rounded-lg">
                <div className="flex items-center gap-3">
                    <Button
                        onClick={handleCompile}
                        disabled={selectedTypes.length === 0 || compileMutation.isPending}
                    >
                        {compileMutation.isPending ? (
                            <Loader2 className="mr-2 h-4 w-4 animate-spin"/>
                        ) : (
                            <Play className="mr-2 h-4 w-4"/>
                        )}
                        사전적용
                        {selectedTypes.length > 0 && (
                            <Badge variant="secondary" className="ml-2">
                                {selectedTypes.length}
                            </Badge>
                        )}
                    </Button>
                </div>

                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => refetch()}
                    disabled={isLoading}
                >
                    <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`}/>
                </Button>
            </div>

            {/* Table */}
            <div className="rounded-md border bg-background">
                {isLoading ? (
                    <div className="flex items-center justify-center h-64">
                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground"/>
                    </div>
                ) : isError ? (
                    <div className="flex flex-col items-center justify-center h-64 text-muted-foreground">
                        <AlertCircle className="h-8 w-8 mb-2"/>
                        <p>데이터를 불러오는데 실패했습니다.</p>
                        <Button variant="link" onClick={() => refetch()}>다시 시도</Button>
                    </div>
                ) : (
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead className="w-[50px]">
                                    <Checkbox
                                        checked={allTypesSelected}
                                        ref={(el) => {
                                            if (el) {
                                                (el as unknown as HTMLInputElement).indeterminate = someTypesSelected;
                                            }
                                        }}
                                        onCheckedChange={(checked) => toggleSelectAll(!!checked)}
                                    />
                                </TableHead>
                                <TableHead>이름</TableHead>
                                <TableHead className="w-[120px]">타입</TableHead>
                                <TableHead className="w-[120px] text-right">단어 수</TableHead>
                                <TableHead className="w-[180px]">수정시간</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {sortedItems.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={5} className="text-center text-muted-foreground h-32">
                                        등록된 사전이 없습니다.
                                    </TableCell>
                                </TableRow>
                            ) : sortedItems.map((item) => item && (
                                <TableRow key={item.type}>
                                    <TableCell>
                                        <Checkbox
                                            checked={selectedTypes.includes(item.type)}
                                            onCheckedChange={(checked) => toggleSelectType(item.type, !!checked)}
                                        />
                                    </TableCell>
                                    <TableCell className="font-medium">
                                        {DICTIONARY_NAMES[item.type]}
                                    </TableCell>
                                    <TableCell>
                                        <Badge variant="outline" className="font-mono text-xs">
                                            {item.type}
                                        </Badge>
                                    </TableCell>
                                    <TableCell className="text-right tabular-nums">
                                        {item.count.toLocaleString()}
                                    </TableCell>
                                    <TableCell className="text-muted-foreground text-sm">
                                        {formatDateTime(item.lastModified)}
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                )}
            </div>

            {/* Summary */}
            <div className="text-sm text-muted-foreground">
                총 {sortedItems.length}개 사전
                {sortedItems.length > 0 && (
                    <span className="ml-2">
            · 전체 단어 수: {sortedItems.reduce((sum, item) => sum + (item?.count || 0), 0).toLocaleString()}개
          </span>
                )}
            </div>
        </div>
    );
}

