  1→"use client";
  2→
  3→import {useState} from "react";
  4→import {Table, TableBody, TableCell, TableHead, TableHeader, TableRow,} from "@/components/ui/table";
  5→import {Input} from "@/components/ui/input";
  6→import {Button} from "@/components/ui/button";
  7→import {Checkbox} from "@/components/ui/checkbox";
  8→import {Badge} from "@/components/ui/badge";
  9→import {Select, SelectContent, SelectItem, SelectTrigger, SelectValue,} from "@/components/ui/select";
 10→import {
 11→    AlertCircle,
 12→    ArrowDownAZ,
 13→    ArrowLeftRight,
 14→    ArrowRight,
 15→    ChevronLeft,
 16→    ChevronRight,
 17→    Clock,
 18→    Eye,
 19→    Loader2,
 20→    Pencil,
 21→    Plus,
 22→    RefreshCw,
 23→    Search,
 24→    Trash2,
 25→} from "lucide-react";
 26→import {
 27→    AlertDialog,
 28→    AlertDialogAction,
 29→    AlertDialogCancel,
 30→    AlertDialogContent,
 31→    AlertDialogDescription,
 32→    AlertDialogFooter,
 33→    AlertDialogHeader,
 34→    AlertDialogTitle,
 35→} from "@/components/ui/alert-dialog";
 36→import {AddDictionaryDialog, EditDictionaryDialog} from "./dictionary-dialogs";
 37→import {useDeleteDictionary, useDictionaries, type SortType} from "@/hooks/use-dictionary";
 38→import type {Dictionary, DictionaryType} from "@/types";
 39→import {DICTIONARY_CATEGORY_MAP} from "@/types";
 40→import {toast} from "sonner";
 41→
 42→interface DictionaryListProps {
 43→    type: DictionaryType;
 44→}
 45→
 46→export function DictionaryList({type}: DictionaryListProps) {
 47→    const [isEditMode, setIsEditMode] = useState(false);
 48→    const [selectedRows, setSelectedRows] = useState<string[]>([]);
 49→    const [addDialogOpen, setAddDialogOpen] = useState(false);
 50→    const [editDialogOpen, setEditDialogOpen] = useState(false);
 51→    const [editingItem, setEditingItem] = useState<Dictionary | null>(null);
 52→    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
 53→
 54→    // Search state
 55→    const [searchValue, setSearchValue] = useState("");
 56→    const [searchField, setSearchField] = useState<'all' | 'keyword' | 'value'>('all');
 57→    const [wordMatch, setWordMatch] = useState(false);
 58→    const [pageSize] = useState(20);
 59→    const [sortType, setSortType] = useState<SortType>('UPDATED');
 60→
 61→    // Cursor-based pagination state
 62→    const [currentCursor, setCurrentCursor] = useState<string | null>(null);
 63→    const [cursorHistory, setCursorHistory] = useState<(string | null)[]>([null]); // Stack of cursors for "previous" navigation
 64→    const [currentPage, setCurrentPage] = useState(1); // For display purposes only
 65→
 66→    // Active search (only updates on Enter or button click)
 67→    const [activeSearch, setActiveSearch] = useState("");
 68→
 69→    const category = DICTIONARY_CATEGORY_MAP[type];
 70→
 71→    // API hooks
 72→    const {data, isLoading, isError, refetch} = useDictionaries({
 73→        type,
 74→        cursor: currentCursor,
 75→        pageSize,
 76→        search: activeSearch || undefined,
 77→        searchField,
 78→        wordMatch,
 79→        sortType,
 80→    });
 81→
 82→    const deleteMutation = useDeleteDictionary();
 83→
 84→    const items = data?.items || [];
 85→    const total = data?.total || 0;
 86→    const hasNext = data?.hasNext || false;
 87→    const nextCursor = data?.nextCursor || null;
 88→    const hasPrevious = cursorHistory.length > 1;
 89→
 90→    // Reset to first page
 91→    const resetPagination = () => {
 92→        setCurrentCursor(null);
 93→        setCursorHistory([null]);
 94→        setCurrentPage(1);
 95→    };
 96→
 97→    const handleSearch = () => {
 98→        resetPagination();
 99→        setActiveSearch(searchValue);
100→    };
101→
102→    const handleSortChange = (newSortType: SortType) => {
103→        if (newSortType !== sortType) {
104→            resetPagination();
105→            setSortType(newSortType);
106→        }
107→    };
108→
109→    const handleKeyDown = (e: React.KeyboardEvent) => {
110→        if (e.key === 'Enter') {
111→            handleSearch();
112→        }
113→    };
114→
115→    // Navigate to next page
116→    const handleNextPage = () => {
117→        if (hasNext && nextCursor) {
118→            setCursorHistory((prev) => [...prev, nextCursor]);
119→            setCurrentCursor(nextCursor);
120→            setCurrentPage((prev) => prev + 1);
121→        }
122→    };
123→
124→    // Navigate to previous page
125→    const handlePreviousPage = () => {
126→        if (hasPrevious) {
127→            const newHistory = [...cursorHistory];
128→            newHistory.pop(); // Remove current cursor
129→            const previousCursor = newHistory[newHistory.length - 1];
130→            setCursorHistory(newHistory);
131→            setCurrentCursor(previousCursor);
132→            setCurrentPage((prev) => Math.max(1, prev - 1));
133→        }
134→    };
135→
136→    // Navigate to first page
137→    const handleFirstPage = () => {
138→        resetPagination();
139→    };
140→
141→    const toggleSelectAll = (checked: boolean) => {
142→        if (checked) {
143→            setSelectedRows(items.map((row) => row.id));
144→        } else {
145→            setSelectedRows([]);
146→        }
147→    };
148→
149→    const toggleSelectRow = (id: string, checked: boolean) => {
150→        if (checked) {
151→            setSelectedRows((prev) => [...prev, id]);
152→        } else {
153→            setSelectedRows((prev) => prev.filter((rowId) => rowId !== id));
154→        }
155→    };
156→
157→    const handleEdit = (item: Dictionary) => {
158→        setEditingItem(item);
159→        setEditDialogOpen(true);
160→    };
161→
162→    const handleDeleteSelected = async () => {
163→        try {
164→            await deleteMutation.mutateAsync({type, ids: selectedRows});
165→            setSelectedRows([]);
166→            setDeleteDialogOpen(false);
167→            toast.success(`${selectedRows.length}개 항목이 삭제되었습니다.`);
168→        } catch (error) {
169→            toast.error('삭제 중 오류가 발생했습니다.');
170→        }
171→    };
172→
173→    // Determine if this is a SYNONYM type to show direction
174→    const isSynonymType = category === 'SYNONYM';
175→    const isSetType = category === 'SET';
176→    const isSpaceType = type === 'SPACE';
177→    const isCompoundType = type === 'COMPOUND';
178→
179→    // Get direction from dictionary item (bidirectional if keyword is null or empty string)
180→    const getDirection = (item: Dictionary) => {
181→        return item.keyword === null || item.keyword === '' ? 'bidirectional' : 'unidirectional';
182→    };
183→
184→    // Render value as badges
185→    const renderValueBadges = (value: string) => {
186→        const parts = value.split(',').map(v => v.trim()).filter(Boolean);
187→        return (
188→            <div className="flex flex-wrap gap-1">
189→                {parts.map((part, i) => (
190→                    <Badge key={i} variant="secondary" className="text-xs font-normal">
191→                        {part}
192→                    </Badge>
193→                ))}
194→            </div>
195→        );
196→    };
197→
198→    return (
199→        <div className="space-y-4">
200→            {/* Toolbar */}
201→            <div className="flex flex-wrap items-center justify-between gap-4 bg-card p-4 border rounded-lg">
202→                <div className="flex items-center gap-2">
203→                    <Select value={searchField} onValueChange={(v) => setSearchField(v as 'all' | 'keyword' | 'value')}>
204→                        <SelectTrigger className="w-[120px]">
205→                            <SelectValue placeholder="필터"/>
206→                        </SelectTrigger>
207→                        <SelectContent>
208→                            <SelectItem value="all">전체</SelectItem>
209→                            {!isSetType && <SelectItem value="keyword">Keyword</SelectItem>}
210→                            <SelectItem value="value">{isSetType ? '단어' : 'Value'}</SelectItem>
211→                        </SelectContent>
212→                    </Select>
213→                    <div className="relative">
214→                        <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground"/>
215→                        <Input
216→                            placeholder="검색어 입력 (Enter)"
217→                            className="pl-9 w-[200px]"
218→                            value={searchValue}
219→                            onChange={(e) => setSearchValue(e.target.value)}
220→                            onKeyDown={handleKeyDown}
221→                        />
222→                    </div>
223→                    <div className="flex items-center space-x-2">
224→                        <Checkbox
225→                            id="word-match"
226→                            checked={wordMatch}
227→                            onCheckedChange={(checked) => setWordMatch(!!checked)}
228→                        />
229→                        <label htmlFor="word-match" className="text-sm font-medium">
230→                            단어매칭
231→                        </label>
232→                    </div>
233→                    <div className="flex items-center gap-1 border rounded-md p-1">
234→                        <Button
235→                            variant={sortType === 'UPDATED' ? 'secondary' : 'ghost'}
236→                            size="sm"
237→                            className="h-7 px-2"
238→                            onClick={() => handleSortChange('UPDATED')}
239→                        >
240→                            <Clock className="h-3.5 w-3.5 mr-1"/>
241→                            업데이트순
242→                        </Button>
243→                        <Button
244→                            variant={sortType === 'KEYWORD' ? 'secondary' : 'ghost'}
245→                            size="sm"
246→                            className="h-7 px-2"
247→                            onClick={() => handleSortChange('KEYWORD')}
248→                        >
249→                            <ArrowDownAZ className="h-3.5 w-3.5 mr-1"/>
250→                            가나다순
251→                        </Button>
252→                    </div>
253→                </div>
254→
255→                <div className="flex items-center gap-2">
256→                    {isEditMode && (
257→                        <>
258→                            <Button size="sm" onClick={() => setAddDialogOpen(true)}>
259→                                <Plus className="mr-2 h-4 w-4"/>
260→                                추가
261→                            </Button>
262→                            <Button
263→                                variant="destructive"
264→                                size="sm"
265→                                disabled={selectedRows.length === 0}
266→                                onClick={() => setDeleteDialogOpen(true)}
267→                            >
268→                                <Trash2 className="mr-2 h-4 w-4"/>
269→                                삭제 ({selectedRows.length})
270→                            </Button>
271→                        </>
272→                    )}
273→                    <Badge variant="outline" className="text-xs tabular-nums">
274→                        {total.toLocaleString()}건
275→                    </Badge>
276→                    <Button
277→                        variant="outline"
278→                        size="sm"
279→                        onClick={() => refetch()}
280→                        disabled={isLoading}
281→                    >
282→                        <RefreshCw className={`h-4 w-4 ${isLoading ? 'animate-spin' : ''}`}/>
283→                    </Button>
284→                    <Button
285→                        variant={isEditMode ? "secondary" : "outline"}
286→                        size="sm"
287→                        onClick={() => {
288→                            setIsEditMode(!isEditMode);
289→                            setSelectedRows([]);
290→                        }}
291→                    >
292→                        {isEditMode ? (
293→                            <><Eye className="mr-2 h-4 w-4"/>보기</>
294→                        ) : (
295→                            <><Pencil className="mr-2 h-4 w-4"/>수정</>
296→                        )}
297→                    </Button>
298→                </div>
299→            </div>
300→
301→            {/* Table */}
302→            <div className="rounded-md border bg-background">
303→                {isLoading ? (
304→                    <div className="flex items-center justify-center h-64">
305→                        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground"/>
306→                    </div>
307→                ) : isError ? (
308→                    <div className="flex flex-col items-center justify-center h-64 text-muted-foreground">
309→                        <AlertCircle className="h-8 w-8 mb-2"/>
310→                        <p>데이터를 불러오는데 실패했습니다.</p>
311→                        <Button variant="link" onClick={() => refetch()}>다시 시도</Button>
312→                    </div>
313→                ) : (
314→                    <Table>
315→                        <TableHeader>
316→                            <TableRow>
317→                                {isEditMode && (
318→                                    <TableHead className="w-[50px]">
319→                                        <Checkbox
320→                                            checked={selectedRows.length === items.length && items.length > 0}
321→                                            onCheckedChange={(checked) => toggleSelectAll(!!checked)}
322→                                        />
323→                                    </TableHead>
324→                                )}
325→
326→                                {/* SET Type: Just "단어" column */}
327→                                {isSetType && (
328→                                    <>
329→                                        <TableHead>단어</TableHead>
330→                                        <TableHead className="w-[150px]">등록일</TableHead>
331→                                    </>
332→                                )}
333→
334→                                {/* SYNONYM Type: Direction, Representative, Synonyms */}
335→                                {isSynonymType && (
336→                                    <>
337→                                        <TableHead className="w-[90px]">방향</TableHead>
338→                                        <TableHead className="w-[150px]">대표어</TableHead>
339→                                        <TableHead>동의어</TableHead>
340→                                        <TableHead className="w-[120px]">등록일</TableHead>
341→                                    </>
342→                                )}
343→
344→                                {/* SPACE Type: Just keyword (no value column) */}
345→                                {isSpaceType && (
346→                                    <>
347→                                        <TableHead>붙여쓴 말</TableHead>
348→                                        <TableHead className="w-[120px]">등록일</TableHead>
349→                                    </>
350→                                )}
351→
352→                                {/* COMPOUND Type: Original, Arrow, Result */}
353→                                {isCompoundType && (
354→                                    <>
355→                                        <TableHead className="w-[200px]">복합어</TableHead>
356→                                        <TableHead className="w-[40px]"></TableHead>
357→                                        <TableHead>분해 결과</TableHead>
358→                                        <TableHead className="w-[120px]">등록일</TableHead>
359→                                    </>
360→                                )}
361→
362→                                {isEditMode && <TableHead className="text-right w-[100px]">액션</TableHead>}
363→                            </TableRow>
364→                        </TableHeader>
365→                        <TableBody>
366→                            {items.length === 0 ? (
367→                                <TableRow>
368→                                    <TableCell
369→                                        colSpan={
370→                                            (isSetType || isSpaceType ? 2 : 4) + (isEditMode ? 2 : 0)
371→                                        }
372→                                        className="text-center text-muted-foreground h-32"
373→                                    >
374→                                        등록된 데이터가 없습니다.
375→                                    </TableCell>
376→                                </TableRow>
377→                            ) : items.map((item) => (
378→                                <TableRow key={item.id}>
379→                                    {isEditMode && (
380→                                        <TableCell>
381→                                            <Checkbox
382→                                                checked={selectedRows.includes(item.id)}
383→                                                onCheckedChange={(checked) => toggleSelectRow(item.id, !!checked)}
384→                                            />
385→                                        </TableCell>
386→                                    )}
387→
388→                                    {/* SET Type Cells - SET types store word in keyword field */}
389→                                    {isSetType && (
390→                                        <>
391→                                            <TableCell className="font-medium">{item.keyword || item.value}</TableCell>
392→                                            <TableCell className="text-muted-foreground text-sm">
393→                                                {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
394→                                            </TableCell>
395→                                        </>
396→                                    )}
397→
398→                                    {/* SYNONYM Type Cells */}
399→                                    {isSynonymType && (
400→                                        <>
401→                                            <TableCell>
402→                                                {getDirection(item) === 'bidirectional' ? (
403→                                                    <div className="flex items-center gap-1 text-blue-500">
404→                                                        <ArrowLeftRight className="h-4 w-4"/>
405→                                                        <span className="text-xs">양방향</span>
406→                                                    </div>
407→                                                ) : (
408→                                                    <div className="flex items-center gap-1 text-green-500">
409→                                                        <ArrowRight className="h-4 w-4"/>
410→                                                        <span className="text-xs">단방향</span>
411→                                                    </div>
412→                                                )}
413→                                            </TableCell>
414→                                            <TableCell className="font-medium">
415→                                                {item.keyword && item.keyword !== '' ? item.keyword :
416→                                                    <span className="text-muted-foreground">-</span>}
417→                                            </TableCell>
418→                                            <TableCell>{renderValueBadges(item.value)}</TableCell>
419→                                            <TableCell className="text-muted-foreground text-sm">
420→                                                {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
421→                                            </TableCell>
422→                                        </>
423→                                    )}
424→
425→                                    {/* SPACE Type Cells - Just keyword (no value column) */}
426→                                    {isSpaceType && (
427→                                        <>
428→                                            <TableCell className="font-medium">{item.keyword}</TableCell>
429→                                            <TableCell className="text-muted-foreground text-sm">
430→                                                {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
431→                                            </TableCell>
432→                                        </>
433→                                    )}
434→
435→                                    {/* COMPOUND Type Cells */}
436→                                    {isCompoundType && (
437→                                        <>
438→                                            <TableCell className="font-medium">{item.keyword}</TableCell>
439→                                            <TableCell>
440→                                                <ArrowRight className="h-4 w-4 text-muted-foreground"/>
441→                                            </TableCell>
442→                                            <TableCell>{renderValueBadges(item.value)}</TableCell>
443→                                            <TableCell className="text-muted-foreground text-sm">
444→                                                {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
445→                                            </TableCell>
446→                                        </>
447→                                    )}
448→
449→                                    {isEditMode && (
450→                                        <TableCell className="text-right">
451→                                            <Button
452→                                                variant="ghost"
453→                                                size="sm"
454→                                                onClick={() => handleEdit(item)}
455→                                            >
456→                                                수정
457→                                            </Button>
458→                                        </TableCell>
459→                                    )}
460→                                </TableRow>
461→                            ))}
462→                        </TableBody>
463→                    </Table>
464→                )}
465→            </div>
466→
467→            {/* Cursor-based Pagination */}
468→            <div className="flex items-center justify-between">
469→                <div className="text-sm text-muted-foreground">
470→                    총 {total.toLocaleString()}건
471→                    {!activeSearch && ` · 페이지 ${currentPage}`}
472→                </div>
473→                <div className="flex items-center gap-2">
474→                    <Button
475→                        variant="outline"
476→                        size="sm"
477→                        onClick={handleFirstPage}
478→                        disabled={!hasPrevious || isLoading}
479→                    >
480→                        처음
481→                    </Button>
482→                    <Button
483→                        variant="outline"
484→                        size="sm"
485→                        onClick={handlePreviousPage}
486→                        disabled={!hasPrevious || isLoading}
487→                    >
488→                        <ChevronLeft className="h-4 w-4 mr-1"/>
489→                        이전
490→                    </Button>
491→                    <Button
492→                        variant="outline"
493→                        size="sm"
494→                        onClick={handleNextPage}
495→                        disabled={!hasNext || isLoading}
496→                    >
497→                        다음
498→                        <ChevronRight className="h-4 w-4 ml-1"/>
499→                    </Button>
500→                </div>
501→            </div>
502→
503→            {/* Dialogs */}
504→            <AddDictionaryDialog
505→                open={addDialogOpen}
506→                onOpenChange={setAddDialogOpen}
507→                type={type}
508→            />
509→
510→            <EditDictionaryDialog
