"use client";

import {useEffect, useState} from "react";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {RadioGroup, RadioGroupItem} from "@/components/ui/radio-group";
import {Badge} from "@/components/ui/badge";
import {Separator} from "@/components/ui/separator";
import {Alert, AlertDescription} from "@/components/ui/alert";
import {AlertCircle, ArrowLeftRight, ArrowRight, Info, Loader2,} from "lucide-react";
import {useCreateDictionary, useUpdateDictionary} from "@/hooks/use-dictionary";
import type {Dictionary, DictionaryCategory, DictionaryType} from "@/types";
import {DICTIONARY_CATEGORY_MAP, DICTIONARY_TYPE_LABELS} from "@/types";
import {toast} from "sonner";

// ========================================
// Helper Functions
// ========================================

function getCategory(type: DictionaryType): DictionaryCategory {
    return DICTIONARY_CATEGORY_MAP[type];
}

function getTypeLabel(type: DictionaryType): string {
    return DICTIONARY_TYPE_LABELS[type];
}

function parseCommaSeparated(value: string): string[] {
    return value.split(',').map(v => v.trim()).filter(Boolean);
}

// ========================================
// Preview Components
// ========================================

interface SynonymPreviewProps {
    direction: 'bidirectional' | 'unidirectional';
    keyword: string;
    value: string;
}

function SynonymPreview({direction, keyword, value}: SynonymPreviewProps) {
    const synonyms = parseCommaSeparated(value);

    if (synonyms.length === 0) return null;

    return (
        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
            <p className="font-medium text-muted-foreground">적용 미리보기</p>
            {direction === 'bidirectional' ? (
                <div className="space-y-1">
                    {synonyms.slice(0, 2).map((word, i) => (
                        <p key={i} className="text-xs">
                            &quot;{word}&quot; 검색 → {synonyms.map((s, j) => (
                            <Badge key={j} variant="secondary" className="mx-0.5 text-xs">{s}</Badge>
                        ))} 결과
                        </p>
                    ))}
                </div>
            ) : (
                <div className="space-y-1">
                    <p className="text-xs">
                        {synonyms.map((s, i) => (
                            <span key={i}>&quot;{s}&quot;{i < synonyms.length - 1 ? ', ' : ''}</span>
                        ))} 검색 → &quot;{keyword}&quot;로 인식
                    </p>
                    <p className="text-xs text-muted-foreground">
                        &quot;{keyword}&quot; 검색 → &quot;{keyword}&quot;만 결과 (역방향 X)
                    </p>
                </div>
            )}
        </div>
    );
}

interface MapPreviewProps {
    type: DictionaryType;
    keyword: string;
    value: string;
}

function MapPreview({type, keyword, value}: MapPreviewProps) {
    const parts = parseCommaSeparated(value);

    if (!keyword || parts.length === 0) return null;

    return (
        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
            <p className="font-medium text-muted-foreground">
                {type === 'SPACE' ? '변환' : type === 'COMPOUND' ? '색인' : '변환'} 미리보기
            </p>
            <div className="space-y-1">
                <p className="text-xs">
                    &quot;{keyword}&quot; → {parts.map((p, i) => (
                    <Badge key={i} variant="secondary" className="mx-0.5 text-xs">{p}</Badge>
                ))}
                </p>
                {type === 'COMPOUND' && (
                    <p className="text-xs text-muted-foreground">
                        &quot;{parts[0]}&quot; 검색 → &quot;{keyword}&quot; 문서도 검색 가능
                    </p>
                )}
            </div>
        </div>
    );
}

// ========================================
// Add Dictionary Dialog
// ========================================

interface AddDictionaryDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    type: DictionaryType;
}

export function AddDictionaryDialog({open, onOpenChange, type}: AddDictionaryDialogProps) {
    const category = getCategory(type);
    const createMutation = useCreateDictionary();

    // Form state
    const [keyword, setKeyword] = useState("");
    const [value, setValue] = useState("");
    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');

    // Validation
    const [errors, setErrors] = useState<string[]>([]);

    // Reset form when dialog opens
    useEffect(() => {
        if (open) {
            setKeyword("");
            setValue("");
            setSynonymDirection('bidirectional');
            setErrors([]);
        }
    }, [open]);

    const validate = (): boolean => {
        const newErrors: string[] = [];

        if (category === 'SET') {
            if (!value.trim()) {
                newErrors.push("단어를 입력해주세요.");
            }
        } else if (category === 'SYNONYM') {
            if (type === 'SYNONYM') {
                if (synonymDirection === 'bidirectional') {
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.length < 2) {
                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
                    }
                } else {
                    if (!keyword.trim()) {
                        newErrors.push("대표 단어를 입력해주세요.");
                    }
                    if (!value.trim()) {
                        newErrors.push("동의어 목록을 입력해주세요.");
                    }
                    // Check for self-loop
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.includes(keyword.trim())) {
                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
                    }
                }
            } else {
                // UNIT_SYNONYM
                if (!keyword.trim()) {
                    newErrors.push("대상 표현을 입력해주세요.");
                }
                if (!value.trim()) {
                    newErrors.push("정규화 기호를 입력해주세요.");
                }
            }
        } else if (category === 'MAP') {
            if (!keyword.trim()) {
                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
            }
            if (type === 'SPACE' && keyword.includes(' ')) {
                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
            }
            if (!value.trim()) {
                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
            }
            const parts = parseCommaSeparated(value);
            if (parts.length < 2) {
                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
            }
        }

        setErrors(newErrors);
        return newErrors.length === 0;
    };

    const handleSubmit = async () => {
        if (!validate()) return;

        try {
            let finalKeyword: string | null = null;
            let finalValue: string | null = null;

            if (category === 'SET') {
                // SET types (STOP, USER, ENGLISH, UNIT) store word in keyword field
                finalKeyword = value.trim();
                finalValue = null;
            } else if (category === 'SYNONYM') {
                if (type === 'SYNONYM' && synonymDirection === 'bidirectional') {
                    finalKeyword = null;
                } else {
                    finalKeyword = keyword.trim();
                }
                finalValue = value.trim();
            } else if (category === 'MAP') {
                finalKeyword = keyword.trim();
                finalValue = value.trim();
            }

            await createMutation.mutateAsync({
                type,
                keyword: finalKeyword,
                value: finalValue,
            });

            toast.success("사전이 추가되었습니다.");
            onOpenChange(false);
        } catch (error) {
            toast.error("추가 중 오류가 발생했습니다.");
        }
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                    <DialogTitle>{getTypeLabel(type)} 사전 추가</DialogTitle>
                    <DialogDescription>
                        새로운 {getTypeLabel(type)} 항목을 추가합니다.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4 py-4">
                    {/* SET Type Form */}
                    {category === 'SET' && (
                        <div className="space-y-2">
                            <Label htmlFor="value">단어 *</Label>
                            <Input
                                id="value"
                                value={value}
                                onChange={(e) => setValue(e.target.value)}
                                placeholder={
                                    type === 'ENGLISH' ? "예: hello" :
                                        type === 'UNIT' ? "예: kg, cm" :
                                            "예: 그러나, 하지만"
                                }
                            />
                            <p className="text-xs text-muted-foreground">
                                <Info className="inline h-3 w-3 mr-1"/>
                                단순 키워드 등록 - 분석 시 해당 단어로 인식됩니다
                            </p>
                        </div>
                    )}

                    {/* SYNONYM Type Form */}
                    {type === 'SYNONYM' && (
                        <>
                            <div className="space-y-3">
                                <Label>매핑 방향</Label>
                                <RadioGroup
                                    value={synonymDirection}
                                    onValueChange={(v) => setSynonymDirection(v as 'bidirectional' | 'unidirectional')}
                                    className="flex flex-col space-y-2"
                                >
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="bidirectional" id="bidirectional"/>
                                        <Label htmlFor="bidirectional" className="font-normal flex items-center gap-2">
                                            <ArrowLeftRight className="h-4 w-4 text-blue-500"/>
                                            양방향 (상호 동의어)
                                        </Label>
                                    </div>
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="unidirectional" id="unidirectional"/>
                                        <Label htmlFor="unidirectional" className="font-normal flex items-center gap-2">
                                            <ArrowRight className="h-4 w-4 text-green-500"/>
                                            단방향 (대표어 → 동의어)
                                        </Label>
                                    </div>
                                </RadioGroup>
                            </div>

                            <Separator/>

                            {synonymDirection === 'bidirectional' ? (
                                <div className="space-y-2">
                                    <Label htmlFor="synonyms">동의어 그룹 *</Label>
                                    <Input
                                        id="synonyms"
                                        value={value}
                                        onChange={(e) => setValue(e.target.value)}
                                        placeholder="노트북, 랩탑, 휴대용컴퓨터"
                                    />
                                    <p className="text-xs text-muted-foreground">
                                        <Info className="inline h-3 w-3 mr-1"/>
                                        최소 2개 이상 입력 (쉼표 구분)
                                    </p>
                                </div>
                            ) : (
                                <>
                                    <div className="space-y-2">
                                        <Label htmlFor="keyword">대표 단어 *</Label>
                                        <Input
                                            id="keyword"
                                            value={keyword}
                                            onChange={(e) => setKeyword(e.target.value)}
                                            placeholder="컴퓨터"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label htmlFor="synonymValue">동의어 목록 *</Label>
                                        <Input
                                            id="synonymValue"
                                            value={value}
                                            onChange={(e) => setValue(e.target.value)}
                                            placeholder="PC, 피씨, 개인용컴퓨터"
                                        />
                                    </div>
                                </>
                            )}

                            <SynonymPreview
                                direction={synonymDirection}
                                keyword={keyword}
                                value={value}
                            />
                        </>
                    )}

                    {/* UNIT_SYNONYM Type Form */}
                    {type === 'UNIT_SYNONYM' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="keyword">대상 표현 *</Label>
                                <Input
                                    id="keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                    placeholder="킬로그램"
                                />
                                <p className="text-xs text-muted-foreground">사용자가 입력하는 표현</p>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="value">정규화 기호 *</Label>
                                <Input
                                    id="value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                    placeholder="kg"
                                />
                                <p className="text-xs text-muted-foreground">표준화된 단위 기호</p>
                            </div>

                            {keyword && value && (
                                <div className="p-3 bg-muted/50 rounded-lg text-sm">
                                    <p className="font-medium text-muted-foreground">변환 미리보기</p>
                                    <p className="text-xs mt-1">
                                        &quot;5 {keyword}&quot; 검색 → &quot;5 {value}&quot;로 인식
                                    </p>
                                </div>
                            )}
                        </>
                    )}

                    {/* MAP Type Form (SPACE, COMPOUND) */}
                    {category === 'MAP' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="keyword">
                                    {type === 'SPACE' ? '붙여쓴 말' : '복합어'} *
                                </Label>
                                <Input
                                    id="keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                    placeholder={type === 'SPACE' ? "삼성전자" : "고무장갑"}
                                />
                                {type === 'SPACE' && (
                                    <p className="text-xs text-muted-foreground">
                                        <Info className="inline h-3 w-3 mr-1"/>
                                        공백 없이 입력
                                    </p>
                                )}
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="value">
                                    {type === 'SPACE' ? '분리 결과' : '분해 결과'} *
                                </Label>
                                <Input
                                    id="value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                    placeholder={type === 'SPACE' ? "삼성, 전자" : "고무, 장갑"}
                                />
                                <p className="text-xs text-muted-foreground">쉼표 또는 공백으로 구분</p>
                            </div>

                            <MapPreview type={type} keyword={keyword} value={value}/>
                        </>
                    )}

                    {/* Validation Errors */}
                    {errors.length > 0 && (
                        <Alert variant="destructive">
                            <AlertCircle className="h-4 w-4"/>
                            <AlertDescription>
                                <ul className="list-disc list-inside">
                                    {errors.map((error, i) => (
                                        <li key={i}>{error}</li>
                                    ))}
                                </ul>
                            </AlertDescription>
                        </Alert>
                    )}
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        취소
                    </Button>
                    <Button onClick={handleSubmit} disabled={createMutation.isPending}>
                        {createMutation.isPending && (
                            <Loader2 className="mr-2 h-4 w-4 animate-spin"/>
                        )}
                        추가
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

// ========================================
// Edit Dictionary Dialog
// ========================================

interface EditDictionaryDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    type: DictionaryType;
    item: Dictionary | null;
}

export function EditDictionaryDialog({open, onOpenChange, type, item}: EditDictionaryDialogProps) {
    const category = getCategory(type);
    const updateMutation = useUpdateDictionary();

    // Form state
    const [keyword, setKeyword] = useState("");
    const [value, setValue] = useState("");
    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');

    // Validation
    const [errors, setErrors] = useState<string[]>([]);

    // Initialize form when item changes
    useEffect(() => {
        if (item) {
            setKeyword(item.keyword || "");
            // SET types store word in keyword field, other types use value
            if (category === 'SET') {
                setValue(item.keyword || "");
            } else {
                setValue(item.value || "");
            }
            setSynonymDirection(item.keyword === null ? 'bidirectional' : 'unidirectional');
            setErrors([]);
        }
    }, [item, category]);

    const validate = (): boolean => {
        const newErrors: string[] = [];

        if (category === 'SET') {
            if (!value.trim()) {
                newErrors.push("단어를 입력해주세요.");
            }
        } else if (category === 'SYNONYM') {
            if (type === 'SYNONYM') {
                if (synonymDirection === 'bidirectional') {
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.length < 2) {
                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
                    }
                } else {
                    if (!keyword.trim()) {
                        newErrors.push("대표 단어를 입력해주세요.");
                    }
                    if (!value.trim()) {
                        newErrors.push("동의어 목록을 입력해주세요.");
                    }
                    const synonyms = parseCommaSeparated(value);
                    if (synonyms.includes(keyword.trim())) {
                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
                    }
                }
            } else {
                if (!keyword.trim()) {
                    newErrors.push("대상 표현을 입력해주세요.");
                }
                if (!value.trim()) {
                    newErrors.push("정규화 기호를 입력해주세요.");
                }
            }
        } else if (category === 'MAP') {
            if (!keyword.trim()) {
                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
            }
            if (type === 'SPACE' && keyword.includes(' ')) {
                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
            }
            if (!value.trim()) {
                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
            }
            const parts = parseCommaSeparated(value);
            if (parts.length < 2) {
                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
            }
        }

        setErrors(newErrors);
        return newErrors.length === 0;
    };

    const handleSubmit = async () => {
        if (!item || !validate()) return;

        try {
            let finalKeyword: string | null = null;
            let finalValue: string | null = null;

            if (category === 'SET') {
                // SET types (STOP, USER, ENGLISH, UNIT) store word in keyword field
                finalKeyword = value.trim();
                finalValue = null;
            } else if (category === 'SYNONYM') {
                if (type === 'SYNONYM' && synonymDirection === 'bidirectional') {
                    finalKeyword = null;
                } else {
                    finalKeyword = keyword.trim();
                }
                finalValue = value.trim();
            } else if (category === 'MAP') {
                finalKeyword = keyword.trim();
                finalValue = value.trim();
            }

            await updateMutation.mutateAsync({
                type,
                id: item.id,
                keyword: finalKeyword,
                value: finalValue,
            });

            toast.success("사전이 수정되었습니다.");
            onOpenChange(false);
        } catch (error) {
            toast.error("수정 중 오류가 발생했습니다.");
        }
    };

    if (!item) return null;

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                    <DialogTitle>{getTypeLabel(type)} 사전 수정</DialogTitle>
                    <DialogDescription>
                        기존 {getTypeLabel(type)} 항목을 수정합니다.
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4 py-4">
                    {/* SET Type Form */}
                    {category === 'SET' && (
                        <div className="space-y-2">
                            <Label htmlFor="value">단어 *</Label>
                            <Input
                                id="value"
                                value={value}
                                onChange={(e) => setValue(e.target.value)}
                            />
                        </div>
                    )}

                    {/* SYNONYM Type Form */}
                    {type === 'SYNONYM' && (
                        <>
                            <div className="space-y-3">
                                <Label>매핑 방향</Label>
                                <RadioGroup
                                    value={synonymDirection}
                                    onValueChange={(v) => setSynonymDirection(v as 'bidirectional' | 'unidirectional')}
                                    className="flex flex-col space-y-2"
                                >
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="bidirectional" id="edit-bidirectional"/>
                                        <Label htmlFor="edit-bidirectional"
                                               className="font-normal flex items-center gap-2">
                                            <ArrowLeftRight className="h-4 w-4 text-blue-500"/>
                                            양방향 (상호 동의어)
                                        </Label>
                                    </div>
                                    <div className="flex items-center space-x-2">
                                        <RadioGroupItem value="unidirectional" id="edit-unidirectional"/>
                                        <Label htmlFor="edit-unidirectional"
                                               className="font-normal flex items-center gap-2">
                                            <ArrowRight className="h-4 w-4 text-green-500"/>
                                            단방향 (대표어 → 동의어)
                                        </Label>
                                    </div>
                                </RadioGroup>
                            </div>

                            <Separator/>

                            {synonymDirection === 'bidirectional' ? (
                                <div className="space-y-2">
                                    <Label htmlFor="edit-synonyms">동의어 그룹 *</Label>
                                    <Input
                                        id="edit-synonyms"
                                        value={value}
                                        onChange={(e) => setValue(e.target.value)}
                                    />
                                </div>
                            ) : (
                                <>
                                    <div className="space-y-2">
                                        <Label htmlFor="edit-keyword">대표 단어 *</Label>
                                        <Input
                                            id="edit-keyword"
                                            value={keyword}
                                            onChange={(e) => setKeyword(e.target.value)}
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <Label htmlFor="edit-synonymValue">동의어 목록 *</Label>
                                        <Input
                                            id="edit-synonymValue"
                                            value={value}
                                            onChange={(e) => setValue(e.target.value)}
                                        />
                                    </div>
                                </>
                            )}

                            <SynonymPreview
                                direction={synonymDirection}
                                keyword={keyword}
                                value={value}
                            />
                        </>
                    )}

                    {/* UNIT_SYNONYM Type Form */}
                    {type === 'UNIT_SYNONYM' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="edit-unit-keyword">대상 표현 *</Label>
                                <Input
                                    id="edit-unit-keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="edit-unit-value">정규화 기호 *</Label>
                                <Input
                                    id="edit-unit-value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                />
                            </div>
                        </>
                    )}

                    {/* MAP Type Form */}
                    {category === 'MAP' && (
                        <>
                            <div className="space-y-2">
                                <Label htmlFor="edit-map-keyword">
                                    {type === 'SPACE' ? '붙여쓴 말' : '복합어'} *
                                </Label>
                                <Input
                                    id="edit-map-keyword"
                                    value={keyword}
                                    onChange={(e) => setKeyword(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="edit-map-value">
                                    {type === 'SPACE' ? '분리 결과' : '분해 결과'} *
                                </Label>
                                <Input
                                    id="edit-map-value"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                />
                            </div>

                            <MapPreview type={type} keyword={keyword} value={value}/>
                        </>
                    )}

                    {/* Validation Errors */}
                    {errors.length > 0 && (
                        <Alert variant="destructive">
                            <AlertCircle className="h-4 w-4"/>
                            <AlertDescription>
                                <ul className="list-disc list-inside">
                                    {errors.map((error, i) => (
                                        <li key={i}>{error}</li>
                                    ))}
                                </ul>
                            </AlertDescription>
                        </Alert>
                    )}
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        취소
                    </Button>
                    <Button onClick={handleSubmit} disabled={updateMutation.isPending}>
                        {updateMutation.isPending && (
                            <Loader2 className="mr-2 h-4 w-4 animate-spin"/>
                        )}
                        저장
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

