// ──────────────────────────────────────────────
// Search Admin REST API Client
// Routes through Next.js rewrites (/search-admin-api/*) to avoid CORS
// Backend URL configured server-side in next.config.ts
// ──────────────────────────────────────────────

const SEARCH_ADMIN_BASE_PATH = '/search-admin-api/api'

export class SearchAdminApiError extends Error {
  status: number
  detail?: string

  constructor(status: number, message: string, detail?: string) {
    super(detail ?? message)
    this.name = 'SearchAdminApiError'
    this.status = status
    this.detail = detail
  }
}

const createSearchAdminError = async (response: Response): Promise<SearchAdminApiError> => {
  let detail: string | undefined
  try {
    const body = await response.json()
    detail = body.message ?? body.error ?? JSON.stringify(body)
  } catch {
    detail = response.statusText
  }
  return new SearchAdminApiError(response.status, `API Error (${response.status})`, detail)
}

interface RequestOptions extends Omit<RequestInit, 'body'> {
  body?: unknown
  params?: Record<string, string | number | boolean | undefined>
}

const buildUrl = (path: string, params?: Record<string, string | number | boolean | undefined>): string => {
  const fullPath = path.startsWith('/') ? `${SEARCH_ADMIN_BASE_PATH}${path}` : `${SEARCH_ADMIN_BASE_PATH}/${path}`
  if (!params) return fullPath

  const searchParams = new URLSearchParams()
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined) {
      searchParams.set(key, String(value))
    }
  })
  const qs = searchParams.toString()
  return qs ? `${fullPath}?${qs}` : fullPath
}

const searchAdminFetch = async <T>(path: string, options: RequestOptions = {}): Promise<T> => {
  const { body, params, headers, ...restOptions } = options

  const url = buildUrl(path, params)

  const response = await fetch(url, {
    ...restOptions,
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  })

  if (!response.ok) {
    throw await createSearchAdminError(response)
  }

  if (response.status === 204) {
    return undefined as T
  }

  return response.json()
}

export const searchAdminApi = {
  get: <T>(path: string, params?: Record<string, string | number | boolean | undefined>) =>
    searchAdminFetch<T>(path, { method: 'GET', params }),

  post: <T>(path: string, body?: unknown) => searchAdminFetch<T>(path, { method: 'POST', body }),

  put: <T>(path: string, body?: unknown) => searchAdminFetch<T>(path, { method: 'PUT', body }),

  delete: <T>(path: string, body?: unknown) => searchAdminFetch<T>(path, { method: 'DELETE', body }),
} as const

