    [...searchDictionaryKeys.dictionaries(), type, { cursor, search, sortType }] as const,
  dictionaryOverview: () => [...searchDictionaryKeys.all, 'overview'] as const,
}

// ========================================
// Dictionary List Hook (Cursor-based)
// ========================================

export type SortType = 'UPDATED' | 'KEYWORD'

interface SearchDictionaryListParams {
  type: SearchDictionaryType
  cursor?: string | null
  pageSize?: number
  search?: string
  searchField?: 'all' | 'keyword' | 'value'
