'use client'

import { useState } from 'react'
import { Button, Table, Tag, message } from 'antd'
import type { TableColumnsType } from 'antd'
import { LoadingOutlined, PlayCircleOutlined, ReloadOutlined } from '@ant-design/icons'
import { useCompileSearchDictionary, useSearchDictionaryOverview } from '../model/useSearchDictionary'
import type { SearchDictionaryOverviewItem, SearchDictionaryType } from '../model/types'
import { SEARCH_DICTIONARY_NAMES } from '../model/types'

const DICTIONARY_TYPE_ORDER: SearchDictionaryType[] = [
  'STOP',
  'USER',
  'ENGLISH',
  'UNIT',
  'SYNONYM',
  'UNIT_SYNONYM',
  'SPACE',
  'COMPOUND',
]

const formatDateTime = (dateString: string | null) => {
  if (!dateString) return '-'
  const date = new Date(dateString)
  return date.toLocaleString('ko-KR', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export const SearchDictionaryOverview = () => {
  const [selectedTypes, setSelectedTypes] = useState<SearchDictionaryType[]>([])

  const { data, isLoading, isError, refetch } = useSearchDictionaryOverview()
  const compileMutation = useCompileSearchDictionary()

  const items = data?.items || []

  const sortedItems = DICTIONARY_TYPE_ORDER.map((type) =>
    items.find((item) => item.type === type),
  ).filter((item): item is SearchDictionaryOverviewItem => !!item)

  const handleCompile = async () => {
    if (selectedTypes.length === 0) return

    try {
      const results = await compileMutation.mutateAsync({ types: selectedTypes })
      const totalCount = results.reduce((sum, r) => sum + r.count, 0)
      message.success(`${selectedTypes.length}개 사전이 적용되었습니다. (총 ${totalCount.toLocaleString()}개 단어)`)
      setSelectedTypes([])
    } catch {
      message.error('사전 적용 중 오류가 발생했습니다.')
    }
  }

  const columns: TableColumnsType<SearchDictionaryOverviewItem> = [
    {
      title: '이름',
      dataIndex: 'type',
      key: 'name',
      render: (type: SearchDictionaryType) => (
        <span className="font-medium">{SEARCH_DICTIONARY_NAMES[type]}</span>
      ),
    },
    {
      title: '타입',
      dataIndex: 'type',
      key: 'type',
      width: 120,
      render: (type: SearchDictionaryType) => (
        <Tag className="font-mono text-xs">{type}</Tag>
      ),
    },
    {
      title: '단어 수',
      dataIndex: 'count',
      key: 'count',
      width: 120,
      align: 'right',
      render: (count: number) => (
        <span className="tabular-nums">{count.toLocaleString()}</span>
      ),
    },
    {
      title: '수정시간',
      dataIndex: 'lastModified',
      key: 'lastModified',
      width: 180,
      render: (lastModified: string | null) => (
        <span className="text-sm text-gray-500">{formatDateTime(lastModified)}</span>
      ),
    },
  ]

  return (
    <div className="flex flex-col gap-4">
      {/* Toolbar */}
      <div className="flex items-center justify-between rounded-lg border bg-white p-4">
        <div className="flex items-center gap-3">
          <Button
            type="primary"
            icon={compileMutation.isPending ? <LoadingOutlined /> : <PlayCircleOutlined />}
            onClick={handleCompile}
            disabled={selectedTypes.length === 0}
            loading={compileMutation.isPending}
          >
            사전적용
            {selectedTypes.length > 0 && (
              <Tag className="ml-2">{selectedTypes.length}</Tag>
            )}
          </Button>
        </div>

        <Button
          icon={<ReloadOutlined spin={isLoading} />}
          onClick={() => refetch()}
          disabled={isLoading}
        />
      </div>

      {/* Table */}
      <Table<SearchDictionaryOverviewItem>
        rowKey="type"
        size="small"
        loading={isLoading}
        dataSource={sortedItems}
        columns={columns}
        pagination={false}
        rowSelection={{
          selectedRowKeys: selectedTypes,
          onChange: (keys) => setSelectedTypes(keys as SearchDictionaryType[]),
        }}
        locale={{
          emptyText: isError ? '데이터를 불러오는데 실패했습니다.' : '등록된 사전이 없습니다.',
        }}
      />

      {/* Summary */}
      <div className="text-sm text-gray-500">
        총 {sortedItems.length}개 사전
        {sortedItems.length > 0 && (
          <span className="ml-2">
            · 전체 단어 수: {sortedItems.reduce((sum, item) => sum + (item?.count || 0), 0).toLocaleString()}개
          </span>
        )}
      </div>
    </div>
  )
}

