          <Input.Search
            placeholder="검색어 입력 (Enter)"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
            onSearch={handleSearch}
            style={{ width: 200 }}
            allowClear
          />
          <Checkbox checked={wordMatch} onChange={(e) => setWordMatch(e.target.checked)}>
            단어매칭
          </Checkbox>
          <Button.Group>
            <Button
              type={sortType === 'UPDATED' ? 'primary' : 'default'}
              size="small"
              icon={<SortAscendingOutlined />}
              onClick={() => handleSortChange('UPDATED')}
            >
              업데이트순
            </Button>
            <Button
              type={sortType === 'KEYWORD' ? 'primary' : 'default'}
              size="small"
              onClick={() => handleSortChange('KEYWORD')}
            >
              가나다순
            </Button>
          </Button.Group>
        </div>

        <div className="flex items-center gap-2">
          {isEditMode && (
            <>
              <Button type="primary" size="small" icon={<PlusOutlined />} onClick={() => setAddModalOpen(true)}>
                추가
              </Button>
              <Button
                danger
                size="small"
                icon={<DeleteOutlined />}
                disabled={selectedRows.length === 0}
                onClick={handleDeleteSelected}
              >
                삭제 ({selectedRows.length})
              </Button>
            </>
          )}
          <Tag>{total.toLocaleString()}건</Tag>
          <Button
            icon={<ReloadOutlined spin={isLoading} />}
            size="small"
            onClick={() => refetch()}
            disabled={isLoading}
          />
          <Button
            type={isEditMode ? 'primary' : 'default'}
            size="small"
            icon={isEditMode ? <EyeOutlined /> : <EditOutlined />}
            onClick={() => {
              setIsEditMode(!isEditMode)
              setSelectedRows([])
            }}
          >
            {isEditMode ? '보기' : '수정'}
          </Button>
        </div>
      </div>

      {/* Table */}
      <Table<SearchDictionaryEntry>
        rowKey="id"
        size="small"
        loading={isLoading}
        dataSource={items}
        columns={buildColumns()}
        pagination={false}
        rowSelection={
          isEditMode
            ? {
                selectedRowKeys: selectedRows,
                onChange: (keys) => setSelectedRows(keys as string[]),
              }
            : undefined
        }
        locale={{
          emptyText: isError ? '데이터를 불러오는데 실패했습니다.' : '등록된 데이터가 없습니다.',
        }}
      />

      {/* Cursor-based Pagination */}
      <div className="flex items-center justify-between">
        <div className="text-sm text-gray-500">
          총 {total.toLocaleString()}건
          {!activeSearch && ` · 페이지 ${currentPage}`}
        </div>
        <div className="flex items-center gap-2">
          <Button size="small" onClick={handleFirstPage} disabled={!hasPrevious || isLoading}>
            처음
          </Button>
          <Button
            size="small"
            icon={<LeftOutlined />}
            onClick={handlePreviousPage}
            disabled={!hasPrevious || isLoading}
          >
            이전
          </Button>
          <Button
            size="small"
            onClick={handleNextPage}
            disabled={!hasNext || isLoading}
          >
            다음
            <RightOutlined />
          </Button>
        </div>
      </div>

      {/* Modals */}
      <SearchDictionaryAddModal
        open={addModalOpen}
        onClose={() => setAddModalOpen(false)}
        type={type}
      />

      <SearchDictionaryEditModal
        open={editModalOpen}
        onClose={() => setEditModalOpen(false)}
        type={type}
        item={editingItem}
      />
    </div>
  )
}

