'use client'

import { useState } from 'react'
import { Button, Checkbox, Input, Modal, Select, Table, Tag, message } from 'antd'
import type { TableColumnsType } from 'antd'
import {
  DeleteOutlined,
  EditOutlined,
  EyeOutlined,
  LeftOutlined,
  PlusOutlined,
  ReloadOutlined,
  RightOutlined,
  SortAscendingOutlined,
  SwapOutlined,
} from '@ant-design/icons'
import {
  useDeleteSearchDictionary,
  useSearchDictionaries,
  type SortType,
} from '../model/useSearchDictionary'
import type { SearchDictionaryEntry, SearchDictionaryType } from '../model/types'
import { SEARCH_DICTIONARY_CATEGORY_MAP } from '../model/types'
import { SearchDictionaryAddModal } from './modal/SearchDictionaryAddModal'
import { SearchDictionaryEditModal } from './modal/SearchDictionaryEditModal'

interface SearchDictionaryListProps {
  type: SearchDictionaryType
}

export const SearchDictionaryList = ({ type }: SearchDictionaryListProps) => {
  const [isEditMode, setIsEditMode] = useState(false)
  const [selectedRows, setSelectedRows] = useState<string[]>([])
  const [addModalOpen, setAddModalOpen] = useState(false)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editingItem, setEditingItem] = useState<SearchDictionaryEntry | null>(null)

  // Search state
  const [searchValue, setSearchValue] = useState('')
  const [searchField, setSearchField] = useState<'all' | 'keyword' | 'value'>('all')
  const [wordMatch, setWordMatch] = useState(false)
  const [pageSize] = useState(20)
  const [sortType, setSortType] = useState<SortType>('UPDATED')

  // Cursor-based pagination state
  const [currentCursor, setCurrentCursor] = useState<string | null>(null)
  const [cursorHistory, setCursorHistory] = useState<(string | null)[]>([null])
  const [currentPage, setCurrentPage] = useState(1)

  // Active search (only updates on Enter or button click)
  const [activeSearch, setActiveSearch] = useState('')

  const category = SEARCH_DICTIONARY_CATEGORY_MAP[type]

  const { data, isLoading, isError, refetch } = useSearchDictionaries({
    type,
    cursor: currentCursor,
    pageSize,
    search: activeSearch || undefined,
    searchField,
    wordMatch,
    sortType,
  })

  const deleteMutation = useDeleteSearchDictionary()

  const items = data?.items || []
  const total = data?.total || 0
  const hasNext = data?.hasNext || false
  const nextCursor = data?.nextCursor || null
  const hasPrevious = cursorHistory.length > 1

  const resetPagination = () => {
    setCurrentCursor(null)
    setCursorHistory([null])
    setCurrentPage(1)
  }

  const handleSearch = (value: string) => {
    resetPagination()
    setActiveSearch(value)
  }

  const handleSortChange = (newSortType: SortType) => {
    if (newSortType !== sortType) {
      resetPagination()
      setSortType(newSortType)
    }
  }

  const handleNextPage = () => {
    if (hasNext && nextCursor) {
      setCursorHistory((prev) => [...prev, nextCursor])
      setCurrentCursor(nextCursor)
      setCurrentPage((prev) => prev + 1)
    }
  }

  const handlePreviousPage = () => {
    if (hasPrevious) {
      const newHistory = [...cursorHistory]
      newHistory.pop()
      const previousCursor = newHistory[newHistory.length - 1]
      setCursorHistory(newHistory)
      setCurrentCursor(previousCursor)
      setCurrentPage((prev) => Math.max(1, prev - 1))
    }
  }

  const handleFirstPage = () => {
    resetPagination()
  }

  const handleEdit = (item: SearchDictionaryEntry) => {
    setEditingItem(item)
    setEditModalOpen(true)
  }

  const handleDeleteSelected = () => {
    Modal.confirm({
      title: '삭제 확인',
      content: `선택한 ${selectedRows.length}개 항목을 삭제하시겠습니까? 이 작업은 되돌릴 수 없습니다.`,
      okText: '삭제',
      okButtonProps: { danger: true },
      cancelText: '취소',
      onOk: async () => {
        try {
          await deleteMutation.mutateAsync({ type, ids: selectedRows })
          setSelectedRows([])
          message.success(`${selectedRows.length}개 항목이 삭제되었습니다.`)
        } catch {
          message.error('삭제 중 오류가 발생했습니다.')
        }
      },
    })
  }

  const isSynonymType = category === 'SYNONYM'
  const isSetType = category === 'SET'
  const isSpaceType = type === 'SPACE'
  const isCompoundType = type === 'COMPOUND'

  const getDirection = (item: SearchDictionaryEntry) => {
    return item.keyword === null || item.keyword === '' ? 'bidirectional' : 'unidirectional'
  }

  const renderValueTags = (value: string) => {
    const parts = value.split(',').map((v) => v.trim()).filter(Boolean)
    return (
