        {parts.map((part, i) => (
          <Tag key={i}>{part}</Tag>
        ))}
      </div>
    )
  }

  const buildColumns = (): TableColumnsType<SearchDictionaryEntry> => {
    const cols: TableColumnsType<SearchDictionaryEntry> = []

    if (isSetType) {
      cols.push(
        {
          title: '단어',
          key: 'word',
          render: (_, item) => <span className="font-medium">{item.keyword || item.value}</span>,
        },
        {
          title: '등록일',
          key: 'createdAt',
          width: 150,
          render: (_, item) => (
            <span className="text-sm text-gray-500">
              {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
            </span>
          ),
        },
      )
    }

    if (isSynonymType) {
      cols.push(
        {
          title: '방향',
          key: 'direction',
          width: 90,
          render: (_, item) =>
            getDirection(item) === 'bidirectional' ? (
              <span className="flex items-center gap-1 text-blue-500">
                <SwapOutlined />
                <span className="text-xs">양방향</span>
              </span>
            ) : (
              <span className="flex items-center gap-1 text-green-500">
                <RightOutlined />
                <span className="text-xs">단방향</span>
              </span>
            ),
        },
        {
          title: '대표어',
          key: 'keyword',
          width: 150,
          render: (_, item) => (
            <span className="font-medium">
              {item.keyword && item.keyword !== '' ? item.keyword : <span className="text-gray-400">-</span>}
            </span>
          ),
        },
        {
          title: '동의어',
          key: 'value',
          render: (_, item) => renderValueTags(item.value),
        },
        {
          title: '등록일',
          key: 'createdAt',
          width: 120,
          render: (_, item) => (
            <span className="text-sm text-gray-500">
              {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
            </span>
          ),
        },
      )
    }

    if (isSpaceType) {
      cols.push(
        {
          title: '붙여쓴 말',
          key: 'keyword',
          render: (_, item) => <span className="font-medium">{item.keyword}</span>,
        },
        {
          title: '등록일',
          key: 'createdAt',
          width: 120,
          render: (_, item) => (
            <span className="text-sm text-gray-500">
              {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
            </span>
          ),
        },
      )
    }

    if (isCompoundType) {
      cols.push(
        {
          title: '복합어',
          key: 'keyword',
          width: 200,
          render: (_, item) => <span className="font-medium">{item.keyword}</span>,
        },
        {
          title: '',
          key: 'arrow',
          width: 40,
          render: () => <RightOutlined className="text-gray-400" />,
        },
        {
          title: '분해 결과',
          key: 'value',
          render: (_, item) => renderValueTags(item.value),
        },
        {
          title: '등록일',
          key: 'createdAt',
          width: 120,
          render: (_, item) => (
            <span className="text-sm text-gray-500">
              {item.createdAt ? new Date(item.createdAt).toLocaleDateString() : '-'}
            </span>
          ),
        },
      )
    }

    if (isEditMode) {
      cols.push({
        title: '액션',
        key: 'actions',
        width: 80,
        align: 'right',
        render: (_, item) => (
          <Button type="link" size="small" onClick={() => handleEdit(item)}>
            수정
          </Button>
        ),
      })
    }

    return cols
  }

  const searchFieldOptions = [
    { value: 'all', label: '전체' },
    ...(!isSetType ? [{ value: 'keyword', label: 'Keyword' }] : []),
    { value: 'value', label: isSetType ? '단어' : 'Value' },
  ]

  return (
    <div className="flex flex-col gap-4">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-lg border bg-white p-4">
        <div className="flex items-center gap-2">
          <Select
            value={searchField}
            onChange={(v) => setSearchField(v)}
            options={searchFieldOptions}
            style={{ width: 120 }}
          />
          <Input.Search
            placeholder="검색어 입력 (Enter)"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
            onSearch={handleSearch}
            style={{ width: 200 }}
            allowClear
          />
          <Checkbox checked={wordMatch} onChange={(e) => setWordMatch(e.target.checked)}>
            단어매칭
