  const [form] = Form.useForm()
  const category: SearchDictionaryCategory = SEARCH_DICTIONARY_CATEGORY_MAP[type]
  const updateMutation = useUpdateSearchDictionary()
  const synonymDirection = Form.useWatch('synonymDirection', form) ?? 'bidirectional'
  const keyword = Form.useWatch('keyword', form) ?? ''
  const value = Form.useWatch('value', form) ?? ''

  useEffect(() => {
    if (open && item) {
      const initialValues: Record<string, string> = {}

      if (category === 'SET') {
        initialValues.value = item.keyword || ''
      } else {
        initialValues.keyword = item.keyword || ''
        initialValues.value = item.value || ''
      }

      if (type === 'SYNONYM') {
        initialValues.synonymDirection = item.keyword === null ? 'bidirectional' : 'unidirectional'
      }

      form.setFieldsValue(initialValues)
    }
  }, [open, item, category, type, form])

  if (!item) return null

  const handleOk = async () => {
    try {
      const values = await form.validateFields()
      let finalKeyword: string | null = null
      let finalValue: string | null = null

      if (category === 'SET') {
        finalKeyword = values.value.trim()
        finalValue = null
      } else if (category === 'SYNONYM') {
        if (type === 'SYNONYM' && values.synonymDirection === 'bidirectional') {
          finalKeyword = null
        } else {
          finalKeyword = values.keyword.trim()
        }
        finalValue = values.value.trim()
      } else if (category === 'MAP') {
        finalKeyword = values.keyword.trim()
        finalValue = values.value.trim()
      }

      await updateMutation.mutateAsync({
        type,
        id: item.id,
        keyword: finalKeyword,
        value: finalValue,
      })

      message.success('사전이 수정되었습니다.')
      onClose()
