      if (error && typeof error === 'object' && 'errorFields' in error) return
      message.error('수정 중 오류가 발생했습니다.')
    }
  }

  return (
    <Modal
      title={`${SEARCH_DICTIONARY_TYPE_LABELS[type]} 사전 수정`}
