  SearchDictionaryCursorPage,
  SearchDictionaryCursorResponse,
  SearchDictionaryEntry,
  SearchDictionaryOverviewResponse,
  SearchDictionaryType,
} from './types'

// ========================================
// Query Keys
// ========================================

export const searchDictionaryKeys = {
  all: ['searchDictionary'] as const,
  dictionaries: () => [...searchDictionaryKeys.all, 'dictionaries'] as const,
  dictionaryList: (type: SearchDictionaryType, cursor?: string | null, search?: string, sortType?: SortType) =>
    [...searchDictionaryKeys.dictionaries(), type, { cursor, search, sortType }] as const,
  dictionaryOverview: () => [...searchDictionaryKeys.all, 'overview'] as const,
}

// ========================================
// Dictionary List Hook (Cursor-based)
// ========================================

export type SortType = 'UPDATED' | 'KEYWORD'

interface SearchDictionaryListParams {
  type: SearchDictionaryType
  cursor?: string | null
  pageSize?: number
  search?: string
  searchField?: 'all' | 'keyword' | 'value'
  wordMatch?: boolean
  sortType?: SortType
}

export const useSearchDictionaries = (params: SearchDictionaryListParams) => {
  const { type, cursor = null, pageSize = 20, search, wordMatch = false, sortType = 'UPDATED' } = params

  return useQuery({
    queryKey: searchDictionaryKeys.dictionaryList(type, cursor, search, sortType),
    queryFn: async (): Promise<SearchDictionaryCursorPage<SearchDictionaryEntry>> => {
      if (search && search.trim()) {
        const items = await searchAdminApi.get<SearchDictionaryBackendDTO[]>(
          `/v1/dictionary/${type}/search`,
          { word: search, isMatch: wordMatch },
        )
        return {
          items: items.map((item) => ({
            id: item.id,
            type: item.type,
            keyword: item.keyword,
            value: item.value ?? '',
            createdAt: item.createdTime,
            updatedAt: item.updatedTime,
          })),
          total: items.length,
          nextCursor: null,
          hasNext: false,
        }
      }

      const response = await searchAdminApi.get<SearchDictionaryCursorResponse>(
        `/v1/dictionary/${type}`,
        {
          size: pageSize,
          sort: sortType,
          ...(cursor && { cursor }),
        },
      )
      return mapCursorDictionaryResponse(response)
    },
    staleTime: 30000,
  })
}

// ========================================
// Dictionary CRUD Hooks
// ========================================

interface CreateSearchDictionaryParams {
  type: SearchDictionaryType
  keyword?: string | null
  value?: string | null
}

export const useCreateSearchDictionary = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (params: CreateSearchDictionaryParams) => {
      return searchAdminApi.post('/v1/dictionary', {
        keyword: params.keyword,
        type: params.type,
        value: params.value,
      })
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: searchDictionaryKeys.dictionaryList(variables.type),
      })
    },
  })
}

interface UpdateSearchDictionaryParams {
  type: SearchDictionaryType
  id: string
  keyword?: string | null
  value?: string | null
}

export const useUpdateSearchDictionary = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (params: UpdateSearchDictionaryParams) => {
      return searchAdminApi.put(`/v1/dictionary/${params.id}`, {
        keyword: params.keyword ?? '',
        type: params.type,
        value: params.value,
      })
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: searchDictionaryKeys.dictionaryList(variables.type),
      })
    },
  })
}

interface DeleteSearchDictionaryParams {
  type: SearchDictionaryType
  ids: string[]
}

export const useDeleteSearchDictionary = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (params: DeleteSearchDictionaryParams) => {
      await Promise.all(
        params.ids.map((id) => searchAdminApi.delete(`/v1/dictionary/${id}`)),
      )
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: searchDictionaryKeys.dictionaryList(variables.type),
      })
    },
  })
}

// ========================================
// Dictionary Overview Hook
// ========================================

export const useSearchDictionaryOverview = () => {
  return useQuery({
    queryKey: searchDictionaryKeys.dictionaryOverview(),
    queryFn: async (): Promise<SearchDictionaryOverviewResponse> => {
      return searchAdminApi.get<SearchDictionaryOverviewResponse>('/v1/dictionary/last-modified')
    },
    staleTime: 30000,
  })
}

// ========================================
// Dictionary Compile Hook
// ========================================

interface CompileSearchDictionaryParams {
  types: SearchDictionaryType[]
}

export const useCompileSearchDictionary = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (params: CompileSearchDictionaryParams): Promise<SearchDictionaryCompileResult[]> => {
      const { types } = params

      if (types.length === 8) {
        return searchAdminApi.post<SearchDictionaryCompileResult[]>('/v1/dictionary/compile')
      }

      const results = await Promise.all(
        types.map((type) =>
          searchAdminApi.post<SearchDictionaryCompileResult>(`/v1/dictionary/compile/${type}`),
        ),
      )
      return results
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: searchDictionaryKeys.dictionaryOverview(),
      })
    },
  })
}

'use client'

import { useEffect } from 'react'
import { Alert, Divider, Form, Input, Modal, Radio, Tag, message } from 'antd'
import { SwapOutlined, RightOutlined } from '@ant-design/icons'
import { useCreateSearchDictionary } from '../../model/useSearchDictionary'
import type { SearchDictionaryCategory, SearchDictionaryType } from '../../model/types'
import { SEARCH_DICTIONARY_CATEGORY_MAP, SEARCH_DICTIONARY_TYPE_LABELS } from '../../model/types'

const parseCommaSeparated = (value: string): string[] =>
  value.split(',').map((v) => v.trim()).filter(Boolean)

// ========================================
// Preview Components
// ========================================

interface SynonymPreviewProps {
  direction: 'bidirectional' | 'unidirectional'
  keyword: string
  value: string
}

const SynonymPreview = ({ direction, keyword, value }: SynonymPreviewProps) => {
  const synonyms = parseCommaSeparated(value)
  if (synonyms.length === 0) return null

  return (
    <div className="rounded-lg bg-gray-50 p-3 text-sm">
      <p className="font-medium text-gray-500">적용 미리보기</p>
      {direction === 'bidirectional' ? (
        <div className="mt-2 space-y-1">
          {synonyms.slice(0, 2).map((word, i) => (
            <p key={i} className="text-xs">
              &quot;{word}&quot; 검색 →{' '}
              {synonyms.map((s, j) => (
                <Tag key={j} className="mx-0.5 text-xs">{s}</Tag>
              ))}{' '}
              결과
            </p>
          ))}
        </div>
      ) : (
        <div className="mt-2 space-y-1">
          <p className="text-xs">
            {synonyms.map((s, i) => (
              <span key={i}>&quot;{s}&quot;{i < synonyms.length - 1 ? ', ' : ''}</span>
            ))}{' '}
            검색 → &quot;{keyword}&quot;로 인식
          </p>
          <p className="text-xs text-gray-400">
            &quot;{keyword}&quot; 검색 → &quot;{keyword}&quot;만 결과 (역방향 X)
          </p>
        </div>
      )}
    </div>
  )
}

interface MapPreviewProps {
  type: SearchDictionaryType
  keyword: string
  value: string
}

const MapPreview = ({ type, keyword, value }: MapPreviewProps) => {
  const parts = parseCommaSeparated(value)
  if (!keyword || parts.length === 0) return null

  return (
    <div className="rounded-lg bg-gray-50 p-3 text-sm">
      <p className="font-medium text-gray-500">
        {type === 'SPACE' ? '변환' : '색인'} 미리보기
      </p>
      <div className="mt-2 space-y-1">
        <p className="text-xs">
          &quot;{keyword}&quot; →{' '}
          {parts.map((p, i) => (
            <Tag key={i} className="mx-0.5 text-xs">{p}</Tag>
          ))}
        </p>
        {type === 'COMPOUND' && (
          <p className="text-xs text-gray-400">
            &quot;{parts[0]}&quot; 검색 → &quot;{keyword}&quot; 문서도 검색 가능
          </p>
        )}
      </div>
    </div>
  )
}

// ========================================
// Add Modal
// ========================================

interface SearchDictionaryAddModalProps {
  open: boolean
  onClose: () => void
  type: SearchDictionaryType
}

export const SearchDictionaryAddModal = ({ open, onClose, type }: SearchDictionaryAddModalProps) => {
  const [form] = Form.useForm()
  const category: SearchDictionaryCategory = SEARCH_DICTIONARY_CATEGORY_MAP[type]
  const createMutation = useCreateSearchDictionary()
  const synonymDirection = Form.useWatch('synonymDirection', form) ?? 'bidirectional'
  const keyword = Form.useWatch('keyword', form) ?? ''
  const value = Form.useWatch('value', form) ?? ''

  useEffect(() => {
    if (open) {
      form.resetFields()
    }
  }, [open, form])

  const handleOk = async () => {
    try {
      const values = await form.validateFields()
      let finalKeyword: string | null = null
      let finalValue: string | null = null

      if (category === 'SET') {
        finalKeyword = values.value.trim()
        finalValue = null
      } else if (category === 'SYNONYM') {
        if (type === 'SYNONYM' && values.synonymDirection === 'bidirectional') {
          finalKeyword = null
        } else {
          finalKeyword = values.keyword.trim()
        }
        finalValue = values.value.trim()
      } else if (category === 'MAP') {
        finalKeyword = values.keyword.trim()
        finalValue = values.value.trim()
      }

      await createMutation.mutateAsync({ type, keyword: finalKeyword, value: finalValue })
      message.success('사전이 추가되었습니다.')
      onClose()
    } catch (error) {
      if (error && typeof error === 'object' && 'errorFields' in error) return
      message.error('추가 중 오류가 발생했습니다.')
    }
  }

  return (
    <Modal
      title={`${SEARCH_DICTIONARY_TYPE_LABELS[type]} 사전 추가`}
      open={open}
      onOk={handleOk}
      onCancel={onClose}
      confirmLoading={createMutation.isPending}
      okText="추가"
      cancelText="취소"
      width={500}
      destroyOnClose
    >
      <p className="mb-4 text-sm text-gray-500">
        새로운 {SEARCH_DICTIONARY_TYPE_LABELS[type]} 항목을 추가합니다.
      </p>

      <Form form={form} layout="vertical" initialValues={{ synonymDirection: 'bidirectional' }}>
        {/* SET Type */}
        {category === 'SET' && (
          <Form.Item
            name="value"
            label="단어"
            rules={[{ required: true, message: '단어를 입력해주세요.' }]}
          >
            <Input
              placeholder={
                type === 'ENGLISH' ? '예: hello' :
                type === 'UNIT' ? '예: kg, cm' :
                '예: 그러나, 하지만'
              }
            />
          </Form.Item>
        )}

        {/* SYNONYM Type */}
        {type === 'SYNONYM' && (
          <>
            <Form.Item name="synonymDirection" label="매핑 방향">
              <Radio.Group>
                <Radio value="bidirectional">
                  <span className="flex items-center gap-1">
                    <SwapOutlined className="text-blue-500" />
                    양방향 (상호 동의어)
                  </span>
                </Radio>
                <Radio value="unidirectional">
                  <span className="flex items-center gap-1">
                    <RightOutlined className="text-green-500" />
                    단방향 (대표어 → 동의어)
                  </span>
                </Radio>
              </Radio.Group>
            </Form.Item>

            <Divider />

            {synonymDirection === 'bidirectional' ? (
              <Form.Item
                name="value"
                label="동의어 그룹"
                rules={[
                  { required: true, message: '동의어를 입력해주세요.' },
                  {
                    validator: (_, val) => {
                      if (val && parseCommaSeparated(val).length < 2) {
                        return Promise.reject('양방향 동의어는 최소 2개 이상 입력해주세요.')
                      }
                      return Promise.resolve()
                    },
                  },
                ]}
              >
                <Input placeholder="노트북, 랩탑, 휴대용컴퓨터" />
              </Form.Item>
            ) : (
              <>
                <Form.Item
                  name="keyword"
                  label="대표 단어"
                  rules={[{ required: true, message: '대표 단어를 입력해주세요.' }]}
                >
                  <Input placeholder="컴퓨터" />
                </Form.Item>
                <Form.Item
                  name="value"
                  label="동의어 목록"
                  rules={[
                    { required: true, message: '동의어 목록을 입력해주세요.' },
                    {
                      validator: (_, val) => {
                        const kw = form.getFieldValue('keyword')
                        if (val && kw && parseCommaSeparated(val).includes(kw.trim())) {
                          return Promise.reject('대표 단어가 동의어 목록에 포함될 수 없습니다.')
                        }
                        return Promise.resolve()
                      },
                    },
                  ]}
                >
                  <Input placeholder="PC, 피씨, 개인용컴퓨터" />
                </Form.Item>
              </>
            )}

            <SynonymPreview direction={synonymDirection} keyword={keyword} value={value} />
          </>
        )}

        {/* UNIT_SYNONYM Type */}
        {type === 'UNIT_SYNONYM' && (
          <>
            <Form.Item
              name="keyword"
              label="대상 표현"
              rules={[{ required: true, message: '대상 표현을 입력해주세요.' }]}
              extra="사용자가 입력하는 표현"
            >
              <Input placeholder="킬로그램" />
            </Form.Item>
            <Form.Item
              name="value"
              label="정규화 기호"
              rules={[{ required: true, message: '정규화 기호를 입력해주세요.' }]}
              extra="표준화된 단위 기호"
            >
              <Input placeholder="kg" />
            </Form.Item>

            {keyword && value && (
              <div className="rounded-lg bg-gray-50 p-3 text-sm">
                <p className="font-medium text-gray-500">변환 미리보기</p>
                <p className="mt-1 text-xs">
                  &quot;5 {keyword}&quot; 검색 → &quot;5 {value}&quot;로 인식
                </p>
              </div>
            )}
          </>
        )}

        {/* MAP Type (SPACE, COMPOUND) */}
        {category === 'MAP' && (
          <>
            <Form.Item
              name="keyword"
              label={type === 'SPACE' ? '붙여쓴 말' : '복합어'}
              rules={[
                { required: true, message: type === 'SPACE' ? '붙여쓴 말을 입력해주세요.' : '복합어를 입력해주세요.' },
                ...(type === 'SPACE'
                  ? [{
                      validator: (_: unknown, val: string) => {
                        if (val && val.includes(' ')) {
                          return Promise.reject('붙여쓴 말에는 공백이 포함될 수 없습니다.')
                        }
                        return Promise.resolve()
                      },
                    }]
                  : []),
              ]}
              extra={type === 'SPACE' ? '공백 없이 입력' : undefined}
            >
              <Input placeholder={type === 'SPACE' ? '삼성전자' : '고무장갑'} />
            </Form.Item>
            <Form.Item
              name="value"
              label={type === 'SPACE' ? '분리 결과' : '분해 결과'}
              rules={[
                { required: true, message: type === 'SPACE' ? '분리 결과를 입력해주세요.' : '분해 결과를 입력해주세요.' },
                {
                  validator: (_, val) => {
                    if (val && parseCommaSeparated(val).length < 2) {
                      return Promise.reject('결과는 최소 2개 이상의 단어여야 합니다.')
                    }
                    return Promise.resolve()
                  },
                },
              ]}
              extra="쉼표 또는 공백으로 구분"
            >
              <Input placeholder={type === 'SPACE' ? '삼성, 전자' : '고무, 장갑'} />
            </Form.Item>

            <MapPreview type={type} keyword={keyword} value={value} />
          </>
        )}
      </Form>
    </Modal>
  )
}
